106	    public BigDecimal calculateCharge(String procedureCode, PricingContext context) {
107	        if (procedureCode == null || procedureCode.trim().isEmpty()) {
108	            log.warn("Empty procedure code provided");
109	            return BigDecimal.ZERO;
110	        }
111	
112	        BigDecimal baseCharge = resolveBaseCharge(procedureCode);
113	
114	        if (baseCharge.compareTo(BigDecimal.ZERO) == 0) {
115	            log.warn("No pricing found for procedure: {}", procedureCode);
116	            return BigDecimal.ZERO;
117	        }
118	
119	        BigDecimal adjusted = applyAdjustments(procedureCode, baseCharge, context);
120	
121	        BigDecimal withDiscounts = applyDiscounts(procedureCode, adjusted, context);
122	
123	        BigDecimal withSurcharges = applySurcharges(procedureCode, withDiscounts, context);
124	
125	        BigDecimal withTax = applyTax(procedureCode, withSurcharges, context);
126	
127	        BigDecimal rounded = roundToNearestCent(withTax);
128	
129	        BigDecimal final_amount = applyLegacyScript(procedureCode, rounded, context);
130	
131	        log.debug("Calculated charge for {}: {} -> {} -> {} -> {} -> {} -> {}",
132	                procedureCode, baseCharge, adjusted, withDiscounts, withSurcharges, withTax, final_amount);
133	
134	        return final_amount;
135	    }
