137	    private BigDecimal resolveBaseCharge(String procedureCode) {
138	        if (LEGACY_PRICING_TABLE.containsKey(procedureCode)) {
139	            return LEGACY_PRICING_TABLE.get(procedureCode);
140	        }
141	
142	        Optional<Procedure> procedure = procedureRepository.findByProcedureCode(procedureCode);
143	        if (procedure.isPresent()) {
144	            BigDecimal cost = procedure.get().getDefaultCost();
145	            if (cost != null && cost.compareTo(BigDecimal.ZERO) > 0) {
146	                return cost;
147	            }
148	        }
149	
150	        if (procedureCode.startsWith("XR")) {
151	            return new BigDecimal("125.00");
152	        } else if (procedureCode.startsWith("LAB")) {
153	            return new BigDecimal("45.00");
154	        } else if (procedureCode.startsWith("TEL")) {
155	            return new BigDecimal("75.00");
156	        } else if (procedureCode.startsWith("PROC")) {
157	            return new BigDecimal("150.00");
158	        } else if (procedureCode.startsWith("992")) {
159	            return new BigDecimal("110.00");
160	        }
161	
162	        return new BigDecimal("50.00");
163	    }
