165	    private BigDecimal applyAdjustments(String procedureCode, BigDecimal base, PricingContext context) {
166	        String family = PROCEDURE_FAMILIES.get(procedureCode);
167	        if (family == null) {
168	            family = deriveFamilyFromCode(procedureCode);
169	        }
170	
171	        BigDecimal adjusted = base;
172	
173	        switch (family) {
174	            case "OFFICE_VISIT_NEW":
175	                if (Boolean.TRUE.equals(context.isFirstVisit())) {
176	                    adjusted = adjusted.multiply(new BigDecimal("1.15"));
177	                }
178	                if (context.getComplexityLevel() != null) {
179	                    switch (context.getComplexityLevel()) {
180	                        case "LOW":
181	                            adjusted = adjusted.multiply(new BigDecimal("0.90"));
182	                            break;
183	                        case "MODERATE":
184	                            break;
185	                        case "HIGH":
186	                            adjusted = adjusted.multiply(new BigDecimal("1.20"));
187	                            break;
188	                        case "VERY_HIGH":
189	                            adjusted = adjusted.multiply(new BigDecimal("1.40"));
190	                            break;
191	                    }
192	                }
193	                break;
194	
195	            case "OFFICE_VISIT_ESTABLISHED":
196	                if (context.getTimeSinceLastVisit() != null) {
197	                    int daysSince = context.getTimeSinceLastVisit();
198	                    if (daysSince < 30) {
199	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
200	                    } else if (daysSince > 365) {
201	                        adjusted = adjusted.multiply(new BigDecimal("1.10"));
202	                    }
203	                }
204	                if (context.getComplexityLevel() != null) {
205	                    switch (context.getComplexityLevel()) {
206	                        case "LOW":
207	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
208	                            break;
209	                        case "MODERATE":
210	                            break;
211	                        case "HIGH":
212	                            adjusted = adjusted.multiply(new BigDecimal("1.25"));
213	                            break;
214	                        case "VERY_HIGH":
215	                            adjusted = adjusted.multiply(new BigDecimal("1.50"));
216	                            break;
217	                    }
218	                }
219	                break;
220	
221	            case "RADIOLOGY":
222	                if (Boolean.TRUE.equals(context.isPortable())) {
223	                    adjusted = adjusted.multiply(new BigDecimal("1.30"));
224	                }
225	                if (Boolean.TRUE.equals(context.isWithContrast())) {
226	                    adjusted = adjusted.multiply(new BigDecimal("1.45"));
227	                }
228	                if (context.getNumberOfViews() != null) {
229	                    int views = context.getNumberOfViews();
230	                    if (views == 1) {
231	                        adjusted = adjusted.multiply(new BigDecimal("0.80"));
232	                    } else if (views == 2) {
233	                    } else if (views >= 3) {
234	                        adjusted = adjusted.multiply(new BigDecimal("1.20"));
235	                    }
236	                }
237	                if (Boolean.TRUE.equals(context.isStatOrder())) {
238	                    adjusted = adjusted.multiply(new BigDecimal("1.35"));
239	                }
240	                break;
241	
242	            case "LABORATORY":
243	                if (Boolean.TRUE.equals(context.isStatOrder())) {
244	                    adjusted = adjusted.multiply(new BigDecimal("1.40"));
245	                }
246	                if (Boolean.TRUE.equals(context.isFastingRequired()) && Boolean.TRUE.equals(context.isFastingCompleted())) {
247	                    adjusted = adjusted.multiply(new BigDecimal("1.05"));
248	                }
249	                if (context.getLabPanelSize() != null) {
250	                    int panelSize = context.getLabPanelSize();
251	                    if (panelSize >= 5) {
252	                        adjusted = adjusted.multiply(new BigDecimal("0.90"));
253	                    } else if (panelSize >= 10) {
254	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
255	                    }
256	                }
257	                break;
258	
259	            case "TELEHEALTH":
260	                if (context.getTelehealthPlatform() != null) {
261	                    switch (context.getTelehealthPlatform()) {
262	                        case "VIDEO":
263	                            break;
264	                        case "PHONE":
265	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
266	                            break;
267	                        case "CHAT":
268	                            adjusted = adjusted.multiply(new BigDecimal("0.70"));
269	                            break;
270	                    }
271	                }
272	                if (context.getDuration() != null) {
273	                    int minutes = context.getDuration();
274	                    if (minutes < 15) {
275	                        adjusted = adjusted.multiply(new BigDecimal("0.75"));
276	                    } else if (minutes > 45) {
277	                        adjusted = adjusted.multiply(new BigDecimal("1.25"));
278	                    } else if (minutes > 60) {
279	                        adjusted = adjusted.multiply(new BigDecimal("1.50"));
280	                    }
281	                }
282	                break;
283	
284	            case "PROCEDURE":
285	                if (context.requiresSedation()) {
286	                    adjusted = adjusted.multiply(new BigDecimal("1.40"));
287	                }
288	                if (context.requiresAssistant()) {
289	                    adjusted = adjusted.multiply(new BigDecimal("1.20"));
290	                }
291	                if (context.getAnesthesiaType() != null) {
292	                    switch (context.getAnesthesiaType()) {
293	                        case "LOCAL":
294	                            adjusted = adjusted.multiply(new BigDecimal("1.10"));
295	                            break;
296	                        case "REGIONAL":
297	                            adjusted = adjusted.multiply(new BigDecimal("1.30"));
298	                            break;
299	                        case "GENERAL":
300	                            adjusted = adjusted.multiply(new BigDecimal("1.60"));
301	                            break;
302	                    }
303	                }
304	                break;
305	
306	            default:
307	                log.debug("No specific adjustments for family: {}", family);
308	        }
309	
310	        return adjusted;
311	    }
