313	    private BigDecimal applyDiscounts(String procedureCode, BigDecimal amount, PricingContext context) {
314	        BigDecimal discounted = amount;
315	
316	        if (context.getPatientAge() != null && context.getPatientAge() >= 65) {
317	            BigDecimal seniorDiscount = DISCOUNT_RULES.get("SENIOR");
318	            if (seniorDiscount != null) {
319	                discounted = discounted.multiply(seniorDiscount);
320	            }
321	        }
322	
323	        if (Boolean.TRUE.equals(context.isEmployeeDependent())) {
324	            BigDecimal employeeDiscount = DISCOUNT_RULES.get("EMPLOYEE");
325	            if (employeeDiscount != null) {
326	                discounted = discounted.multiply(employeeDiscount);
327	            }
328	        }
329	
330	        if (Boolean.TRUE.equals(context.isSelfPay())) {
331	            BigDecimal selfPayDiscount = DISCOUNT_RULES.get("SELF_PAY");
332	            if (selfPayDiscount != null) {
333	                discounted = discounted.multiply(selfPayDiscount);
334	            }
335	        }
336	
337	        if (context.hasContractedInsurance()) {
338	            BigDecimal insuranceDiscount = DISCOUNT_RULES.get("INSURANCE_CONTRACTED");
339	            if (insuranceDiscount != null) {
340	                discounted = discounted.multiply(insuranceDiscount);
341	            }
342	        }
343	
344	        String family = PROCEDURE_FAMILIES.get(procedureCode);
345	        if ("LABORATORY".equals(family) && context.getLabPanelSize() != null && context.getLabPanelSize() >= 5) {
346	            BigDecimal bulkDiscount = DISCOUNT_RULES.get("BULK_LAB");
347	            if (bulkDiscount != null) {
348	                discounted = discounted.multiply(bulkDiscount);
349	            }
350	        }
351	
352	        if (context.getCustomDiscountPercent() != null) {
353	            BigDecimal customDiscount = BigDecimal.ONE.subtract(
354	                    context.getCustomDiscountPercent().divide(new BigDecimal("100"), 4, RoundingMode.HALF_UP)
355	            );
356	            discounted = discounted.multiply(customDiscount);
357	        }
358	
359	        return discounted;
360	    }
