362	    private BigDecimal applySurcharges(String procedureCode, BigDecimal amount, PricingContext context) {
363	        BigDecimal surcharged = amount;
364	
365	        if (context.getServiceDateTime() != null) {
366	            ZonedDateTime serviceTime = context.getServiceDateTime();
367	            int hour = serviceTime.getHour();
368	            DayOfWeek dayOfWeek = serviceTime.getDayOfWeek();
369	
370	            if (hour < 7 || hour > 18) {
371	                BigDecimal afterHours = SURCHARGE_RULES.get("AFTER_HOURS");
372	                if (afterHours != null) {
373	                    surcharged = surcharged.multiply(afterHours);
374	                }
375	            }
376	
377	            if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
378	                BigDecimal weekend = SURCHARGE_RULES.get("WEEKEND");
379	                if (weekend != null) {
380	                    surcharged = surcharged.multiply(weekend);
381	                }
382	            }
383	
384	            if (isHoliday(serviceTime.toLocalDate())) {
385	                BigDecimal holiday = SURCHARGE_RULES.get("HOLIDAY");
386	                if (holiday != null) {
387	                    surcharged = surcharged.multiply(holiday);
388	                }
389	            }
390	        }
391	
392	        if (Boolean.TRUE.equals(context.isUrgent())) {
393	            BigDecimal urgent = SURCHARGE_RULES.get("URGENT");
394	            if (urgent != null) {
395	                surcharged = surcharged.multiply(urgent);
396	            }
397	        }
398	
399	        if (Boolean.TRUE.equals(context.isStatOrder())) {
400	            String family = PROCEDURE_FAMILIES.get(procedureCode);
401	            if ("LABORATORY".equals(family)) {
402	                BigDecimal statLab = SURCHARGE_RULES.get("STAT_LAB");
403	                if (statLab != null) {
404	                    surcharged = surcharged.multiply(statLab);
405	                }
406	            }
407	        }
408	
409	        return surcharged;
410	    }
