412	    private BigDecimal applyTax(String procedureCode, BigDecimal amount, PricingContext context) {
413	        String family = PROCEDURE_FAMILIES.get(procedureCode);
414	        if (family == null) {
415	            family = deriveFamilyFromCode(procedureCode);
416	        }
417	
418	        BigDecimal taxRate = BigDecimal.ZERO;
419	
420	        switch (family) {
421	            case "OFFICE_VISIT_NEW":
422	            case "OFFICE_VISIT_ESTABLISHED":
423	            case "TELEHEALTH":
424	                taxRate = BigDecimal.ZERO;
425	                break;
426	            case "RADIOLOGY":
427	            case "LABORATORY":
428	                if (context.getState() != null) {
429	                    switch (context.getState()) {
430	                        case "CA":
431	                            taxRate = new BigDecimal("0.0725");
432	                            break;
433	                        case "TX":
434	                            taxRate = new BigDecimal("0.0625");
435	                            break;
436	                        case "NY":
437	                            taxRate = new BigDecimal("0.08");
438	                            break;
439	                        case "FL":
440	                            taxRate = new BigDecimal("0.06");
441	                            break;
442	                        default:
443	                            taxRate = new BigDecimal("0.05");
444	                    }
445	                } else {
446	                    taxRate = new BigDecimal("0.05");
447	                }
448	                break;
449	            case "PROCEDURE":
450	                taxRate = new BigDecimal("0.03");
451	                break;
452	            default:
453	                taxRate = new BigDecimal("0.05");
454	        }
455	
456	        if (Boolean.TRUE.equals(context.isTaxExempt())) {
457	            taxRate = BigDecimal.ZERO;
458	        }
459	
460	        BigDecimal taxAmount = amount.multiply(taxRate);
461	        return amount.add(taxAmount);
462	    }
