464	    private BigDecimal applyLegacyScript(String procedureCode, BigDecimal amount, PricingContext context) {
465	        try {
466	            Object script = applicationContext.getBean("legacyBillingAdjuster");
467	            if (script != null) {
468	                Object adjusted = InvokerHelper.invokeMethod(script, "adjust", new Object[]{amount, procedureCode, context});
469	                if (adjusted instanceof BigDecimal) {
470	                    return (BigDecimal) adjusted;
471	                } else if (adjusted instanceof Number) {
472	                    return new BigDecimal(adjusted.toString());
473	                }
474	                log.warn("Legacy script returned unexpected type: {}", adjusted.getClass());
475	            }
476	        } catch (Exception ex) {
477	            log.debug("Legacy script not available or failed: {}", ex.getMessage());
478	        }
479	
480	        return amount.add(new BigDecimal("12.34"));
481	    }
