487	    private String deriveFamilyFromCode(String procedureCode) {
488	        if (procedureCode.startsWith("992")) {
489	            if (procedureCode.startsWith("9920")) {
490	                return "OFFICE_VISIT_NEW";
491	            } else {
492	                return "OFFICE_VISIT_ESTABLISHED";
493	            }
494	        } else if (procedureCode.startsWith("XR")) {
495	            return "RADIOLOGY";
496	        } else if (procedureCode.startsWith("LAB")) {
497	            return "LABORATORY";
498	        } else if (procedureCode.startsWith("TEL")) {
499	            return "TELEHEALTH";
500	        } else if (procedureCode.startsWith("PROC")) {
501	            return "PROCEDURE";
502	        }
503	        return "UNKNOWN";
504	    }
