506	    private boolean isHoliday(LocalDate date) {
507	        int month = date.getMonthValue();
508	        int day = date.getDayOfMonth();
509	
510	        if (month == 1 && day == 1) return true;
511	        if (month == 7 && day == 4) return true;
512	        if (month == 12 && day == 25) return true;
513	        if (month == 11 && day >= 22 && day <= 28 && date.getDayOfWeek() == DayOfWeek.THURSDAY) return true;
514	
515	        return false;
516	    }
